try{const saved=JSON.parse(localStorage.getItem('jobsai-demo-v1')||'null');if(saved&&typeof saved==='object'){const clean={};for(const role of roles){if(stages.includes(saved.applications?.[role.id]))clean[role.id]=saved.applications[role.id];}if(saved.applications&&typeof saved.applications==='object')state.applications=clean;for(const role of roles){if(typeof saved.notes?.[role.id]==='string')state.notes[role.id]=saved.notes[role.id].slice(0,1000);}if(saved.jobs&&typeof saved.jobs==='object')state.jobs=saved.jobs;}}catch{}
const save=()=>{try{localStorage.setItem('jobsai-demo-v1',JSON.stringify(state));}catch{}};
function changeTab(tab,update=true){if(!['matches','tracker','interviews','jobs'].includes(tab))tab='matches';$$('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==tab);$$('[data-tab]').forEach(b=>{if(b.dataset.tab===tab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});if(update){const url=new URL(location.href);url.searchParams.set('tab',tab);history.replaceState(null,'',url);}if(tab==='tracker')renderTracker();document.dispatchEvent(new CustomEvent('jobsai:tab',{detail:tab}));}
$$('[data-tab]').forEach(b=>b.addEventListener('click',()=>changeTab(b.dataset.tab)));$$('[data-open-tab]').forEach(b=>b.addEventListener('click',()=>changeTab(b.dataset.openTab)));
function renderRoles(){
 const filter=$('#role-filter').value,query=($('#dashboard-search')?.value||'').trim().toLowerCase(),sort=$('#role-sort')?.value||'recommended';
 const filtered=roles.filter(r=>(filter==='all'||r.mode===filter||(filter==='strong'&&r.fit>=80))&&[r.title,r.company,r.location,...r.met].join(' ').toLowerCase().includes(query));
 if(sort==='fit')filtered.sort((a,b)=>b.fit-a.fit);if(sort==='title')filtered.sort((a,b)=>a.title.localeCompare(b.title));
 const root=$('#role-list');root.replaceChildren();$('#match-count').textContent=String(filtered.length);$('#application-stat').textContent=String(Object.keys(state.applications).length);
 $$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));
 if(!filtered.length){const empty=el('div',undefined,'role-empty');const reset=el('button','Clear search and filters','pill outline small');reset.addEventListener('click',()=>{$('#dashboard-search').value='';$('#role-filter').value='all';renderRoles();});empty.append(el('h3','No sample matches just yet.'),el('p','Try a broader role, skill, or work location. This preview has four fictional roles.'),reset);root.append(empty);return;}
 for(const role of filtered){const card=el('article',undefined,'role-card');const top=el('div',undefined,'role-card-top');const company=el('div',role.company,'role-company');company.append(el('small',role.location+' · Sample role'));top.append(el('span',role.letter,'company-avatar'),company,el('span',`${role.fit}% fit`,'match-score'));const tags=el('div',undefined,'skill-tags');role.met.slice(0,3).forEach(t=>tags.append(el('span','✓ '+t)));const button=el('a','View role & match ↗','pill outline small');button.href=`role.html?id=${encodeURIComponent(role.id)}`;
 const actions=el('div',undefined,'role-actions'),bookmark=el('button',undefined,'role-save');bookmark.setAttribute('aria-label',`${state.applications[role.id]?'Remove':'Save'} ${role.title} ${state.applications[role.id]?'from':'to'} your board`);bookmark.setAttribute('aria-pressed',String(!!state.applications[role.id]));const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 18 22');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M4 2h10a1 1 0 011 1v17l-6-4-6 4V3a1 1 0 011-1Z');svg.append(path);bookmark.append(svg,el('span',state.applications[role.id]?'On your board':'Save role'));bookmark.addEventListener('click',()=>toggleSavedRole(role.id));actions.append(button,bookmark);const heading=el('h3'),roleLink=el('a',role.title);roleLink.href=button.href;heading.append(roleLink);card.append(top,heading,el('p',role.summary),tags,actions);root.append(card);
 }
}
$('#role-filter').addEventListener('change',renderRoles);
const roleDialog=$('#role-dialog');let currentRole=null;
function openRole(id){currentRole=roles.find(r=>r.id===id);if(!currentRole)return;$('#role-dialog-title').textContent=currentRole.title;$('#role-feedback').textContent='';const content=$('#role-dialog-content');content.replaceChildren(el('p',`${currentRole.company} · ${currentRole.location} · Fictional vacancy`));const explain=el('div',undefined,'match-explanation');explain.append(el('h3',`${currentRole.met.length} of ${currentRole.met.length+currentRole.missing.length} requirements matched`));const list=el('ul');currentRole.met.forEach(t=>list.append(el('li','✓ '+t)));currentRole.missing.forEach(t=>list.append(el('li','Missing: '+t)));explain.append(list,el('p','This score is illustrative. It describes sample skill overlap, not a probability of getting hired.','subtle'));content.append(explain);$('#save-role').textContent=state.applications[id]?'Saved to your board':'Save to my board';$('#save-role').disabled=!!state.applications[id];$('#view-application').textContent='Preview application';$('#view-application').disabled=false;roleDialog.showModal();}
$('.dialog-close').addEventListener('click',()=>roleDialog.close());
roleDialog.addEventListener('click',e=>{if(e.target===roleDialog){const r=roleDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)roleDialog.close();}});
$('#save-role').addEventListener('click',()=>{if(!currentRole||state.applications[currentRole.id])return;state.applications[currentRole.id]='Saved';save();$('#save-role').textContent='Saved to your board';$('#save-role').disabled=true;$('#role-feedback').textContent='Saved in this browser. No application was sent.';renderTracker();renderRoles();});
$('#view-application').addEventListener('click',()=>{if($('#application-example'))return;const box=el('section',undefined,'application-preview');box.id='application-example';box.append(el('h3','Alex Lee · Sample application'),el('p',`I’m interested in the ${currentRole.title.toLowerCase()} role at ${currentRole.company}. My profile includes designing an onboarding flow, conducting user interviews, and building prototypes in Figma.`),el('p','I would welcome the chance to discuss how this experience relates to your team’s needs.'));const fact=el('div','✓ Claims aligned to the six facts in the sample profile.','fact good');const flagged=el('div','“Led a team of eight” is not in the profile and was removed.','fact flagged');box.append(fact,flagged,el('p','The fact lock checks against profile facts, not independent evidence. You still review the wording. In the live service, you would then open the employer’s official application. This fictional role has no application URL.','subtle'));$('#role-dialog-content').append(box);$('#view-application').disabled=true;$('#view-application').textContent='Sample preview shown';});
function renderTracker(){
 const board=$('#tracker-board');board.replaceChildren();$('#tracker-count').textContent=String(Object.keys(state.applications).length);$('#application-stat').textContent=String(Object.keys(state.applications).length);
 for(const stage of stages){const members=roles.filter(r=>state.applications[r.id]===stage);const col=el('div',undefined,'tracker-column');const h=el('h3',stage);h.append(el('span',String(members.length)));col.append(h);
  for(const role of members){const item=el('article',undefined,'tracker-item'),select=el('select');select.setAttribute('aria-label',`Stage for ${role.title} at ${role.company}`);stages.forEach(s=>{const o=el('option',s);o.value=s;o.selected=s===stage;select.append(o);});select.addEventListener('change',()=>{if(!stages.includes(select.value))return;state.applications[role.id]=select.value;save();renderTracker();const next=$$('select',board).find(e=>e.getAttribute('aria-label')===select.getAttribute('aria-label'));next?.focus();showToast(`Moved to ${state.applications[role.id]}.`);});
   const notes=el('div',undefined,'tracker-note'),label=el('label','A note for your next step'),input=el('textarea');input.id=`note-${role.id}`;input.maxLength=1000;input.value=state.notes?.[role.id]||'';input.placeholder='Add a reminder…';label.htmlFor=input.id;input.addEventListener('input',()=>{state.notes=state.notes||{};state.notes[role.id]=input.value.slice(0,1000);save();});input.addEventListener('change',()=>showToast('Note saved on this device.'));notes.append(label,input);
   const remove=el('button','Remove from board','remove-role');remove.addEventListener('click',()=>toggleSavedRole(role.id));const heading=el('h4'),link=el('a',role.title);link.href=`role.html?id=${role.id}`;heading.append(link);item.append(heading,el('p',role.company),select,notes,remove);col.append(item);
  }if(!members.length)col.append(el('p','A little space for your next step.','empty-text'));board.append(col);
 }
}
$('#reset-demo').addEventListener('click',()=>{state={applications:{studio:'Interview',labs:'Applied'},jobs:{},notes:{}};save();renderTracker();renderRoles();resetDelivery();$('#reset-demo').textContent='Sample data reset';setTimeout(()=>$('#reset-demo').textContent='Reset sample data',2000);});
const questions=['Tell me about a design decision you changed after user research.','Describe a time you balanced a user need with a technical constraint.','Walk me through a project you would approach differently today.'];let question=0;
$('#next-question').addEventListener('click',()=>{question=(question+1)%questions.length;$('#practice-question').textContent=questions[question];$('#practice-answer').value='';$('#practice-result').hidden=true;$('#practice-answer').focus();});
$('#practice-check').addEventListener('click',()=>{const answer=$('#practice-answer').value.trim();const result=$('#practice-result');result.hidden=false;result.replaceChildren();if(!answer){result.append(el('p','Write a practice answer first. Keep it to your own experience.'));$('#practice-answer').focus();return;}const words=answer.split(/\s+/).length;result.append(el('h3','A structure check, not a score.'),el('p',`${words} words. This local checklist cannot verify your experience or judge answer quality.`));const list=el('ul');list.append(el('li',words>=60?'You have room for a concrete example. Check that the opening sets the scene.':'Add a little more context: what was the project and the problem?'),el('li',/\bI\b/i.test(answer)?'You describe your own role. Make sure it is distinct from the team’s work.':'Make your contribution clear using “I” where it is accurate.'),el('li',/result|learn|change|improv|feedback|outcome/i.test(answer)?'You mention a change or outcome. Check that the example supports it.':'Close with what happened or what you learned, using only facts you know.'));result.append(list,el('p','Practice result, not a certification. No answer is uploaded or saved.'));});
const templates={
 'Spreadsheet clean-up':{title:'A sheet you can work with.',description:'Standardise the sample dates, remove exact duplicate rows, and preserve the original totals. Return a cleaned CSV and a change log.',checks:['Exact duplicate rows removed','Dates use one agreed format','Totals reconciled to the source','CSV and change log both included'],output:'Sample output: 120 rows reviewed, 4 duplicate rows removed, and totals reconciled. The demo does not process an uploaded spreadsheet.'},
 'CV rewrite':{title:'Your profile, clearly told.',description:'Rewrite the sample CV as a concise, readable document using only the facts in the sample profile.',checks:['Every claim maps to a profile fact','Unsupported leadership claim removed','Readable one-to-two-page format','CV and change notes both included'],output:'Sample output: a concise CV based on six profile facts. The unsupported “led a team of eight” claim is removed. No actual CV is generated.'},
 'Translation + screenshots':{title:'The words, in their context.',description:'Translate a sample menu into French and provide screenshots showing each translated item in the agreed layout.',checks:['All source items accounted for','Names and quantities preserved','Screenshots supplied for each view','Terms checked against the brief'],output:'Sample output: 12 translated menu items with 3 screenshot views. This demonstrates a receipt, not an actual translation service.'},
 'Pricing research table':{title:'A comparison you can follow.',description:'Compare three fictional product plans in a consistent table, recording the sources and dates for each field.',checks:['All three products compared','Price and billing period recorded','Source references included','Unknown fields marked clearly'],output:'Sample output: a three-product comparison with source columns and checked dates. No live market research was performed.'},
 'Product description set':{title:'A consistent voice for your products.',description:'Create a sample set of five concise product descriptions from supplied feature lists and a simple tone guide.',checks:['Five descriptions included','All product claims use supplied facts','Length and tone follow the brief','No invented performance claims'],output:'Sample output: five descriptions with consistent length and feature coverage. This is an illustrative delivery summary.'}
};
let activeTemplate='Spreadsheet clean-up',busy=false,runToken=0;
function setTemplate(name){activeTemplate=Object.hasOwn(templates,name)?name:'Spreadsheet clean-up';const t=templates[activeTemplate];$('#template-select').value=activeTemplate;$('#sample-plan-title').textContent=t.title;$('#sample-plan-description').textContent=t.description;$('#sample-checks').replaceChildren(...t.checks.map(c=>el('li',c)));resetDelivery();}
function resetDelivery(){runToken++;busy=false;$('#template-select').disabled=false;$('#run-job').disabled=false;$('#run-job').textContent='Run sample checks';$('#run-job').removeAttribute('aria-busy');$('#review-actions').hidden=true;$('#delivery-status').textContent='Ready to explore';$('#job-live').textContent='';$('#delivery-content').replaceChildren(el('span','✳','delivery-star'),el('h2','Let’s see what “done” looks like.'),el('p','Run the sample checks to reveal an illustrative delivery and its check receipt.'));if(['accepted','redo'].includes(state.jobs[activeTemplate]))$('#job-live').textContent=`Previous sample choice: ${state.jobs[activeTemplate]==='accepted'?'accepted':'redo requested'}. Run again to explore the flow.`;}
$('#template-select').addEventListener('change',()=>setTemplate($('#template-select').value));
$('#run-job').addEventListener('click',()=>{if(busy)return;busy=true;const token=++runToken;const name=activeTemplate;$('#run-job').disabled=true;$('#run-job').setAttribute('aria-busy','true');$('#run-job').textContent='Running sample checks…';$('#template-select').disabled=true;$('#delivery-status').textContent='Checking sample';$('#job-live').textContent='Running an illustrative check sequence on sample data.';setTimeout(()=>{if(activeTemplate!==name||token!==runToken)return;const t=templates[name];const content=$('#delivery-content');content.replaceChildren(el('h2','Checks passed. Your turn.'),el('p',t.output));const receipt=el('div',undefined,'receipt');receipt.append(el('h3','Sample check receipt'));for(const c of t.checks){const row=el('div',undefined,'receipt-row');row.append(el('span',c),el('span','✓ Sample pass'));receipt.append(row);}receipt.append(el('p','Sample only: no models were called. Automated rule checks, model-assisted review, timed auto-acceptance, and default refunds after a review deadline are planned, not active. In live jobs, client acceptance starts payment; disputes pause for team review.','receipt-note'));content.append(receipt);$('#delivery-status').textContent='Ready for your review';$('#review-actions').hidden=false;$('#accept-job').disabled=false;$('#redo-job').disabled=false;$('#job-live').textContent='The result is ready for your review. No money has moved.';$('#run-job').textContent='Re-run sample checks';$('#run-job').disabled=false;$('#run-job').removeAttribute('aria-busy');$('#template-select').disabled=false;busy=false;},650);});
$('#accept-job').addEventListener('click',()=>{if($('#accept-job').disabled)return;state.jobs[activeTemplate]='accepted';save();$('#delivery-status').textContent='Sample accepted';$('#job-live').textContent='Sample delivery accepted. In a live job, accepting a submission starts payment. This sample did not create a real job or transaction.';$('#accept-job').disabled=true;$('#redo-job').disabled=true;});
$('#redo-job').addEventListener('click',()=>{if($('#redo-job').disabled)return;state.jobs[activeTemplate]='redo';save();$('#delivery-status').textContent='Sample redo requested';$('#job-live').textContent='This sample lets you explore requesting changes. Live JobsAI jobs support repeated revisions. Timed deadlines, free-redo limits, and an outside paid reviewer are planned, not active.';$('#accept-job').disabled=true;$('#redo-job').disabled=true;});
